settings.set({plugins: [GravityChartsPlugin, YagrPlugin]});

const GravityChart = React.lazy(async () => {
    const {ChartKit} = await import('@gravity-ui/chartkit');

    return {default: ChartKit<'gravity-charts'>};
});

const MonitoringChart = React.lazy(async () => {
    const {ChartKit} = await import('@gravity-ui/chartkit');

    return {default: ChartKit<'yagr'>};
});

const modeMeta: Record<VisualizationMode, {title: string; caption: string}> = {
